import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Dated, Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/**
 * A sheet's settings: its clerk limit, with two decimals ('' for no limit), and its floor, the
 * least a claim's live due may be, with two decimals, and its terms, the whole number of days after a
 * claim's date that it is due by, and its late percent, what an overdue claim's due gains per full 30
 * days overdue, with two decimals, and its policy date (yyyy-MM-dd; '' for the sheet's today): a claim
 * dated before it rounds half up, one on or after it half to even, and its period numbering from
 * (yyyy-MM-dd; '' for off): while the sheet's today is on or after it, a claim opened is numbered
 * within its period.
 */
export type Settings = {
  clerkLimit: string;
  floor: string;
  terms: string;
  latePct: string;
  policyDate: string;
  periodNumberingFrom: string;
  /** Each grade's own terms in days ('' for the sheet's terms). */
  gradeTerms: Record<string, string>;
  /** The most a person's due-total may be, with two decimals ('' for none). */
  cap: string;
  /** The due above which a claim, on its date, needs a proof to be settled or approved ('' for none). */
  proofThreshold: string;
  /**
   * Every value recorded for each figure setting, by key (clerk-limit, floor, terms, late-pct,
   * terms-A, terms-B, terms-C, cap, proof-threshold), in from-date order ('' for none). The values above are those
   * in force on the sheet's today.
   */
  dated?: Record<string, { from: string; value: string }[]>;
};

/** The figure settings, which are saved from a from-date, by the key the screen and the store use. */
export const DATED_KEYS = {
  clerkLimit: 'clerk-limit',
  floor: 'floor',
  terms: 'terms',
  latePct: 'late-pct',
  cap: 'cap',
  proofThreshold: 'proof-threshold',
} as const;

/** The grades that may have their own terms. */
export const GRADES = ['A', 'B', 'C'] as const;

/** A save of the settings: only those being changed are sent. */
export type SettingsChange = Partial<Omit<Settings, 'dated'>> & { from?: Record<string, string> };

/** A user's role on a sheet. A name with no role assigned is a clerk. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;

export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/**
 * The sheet's floor, dated: 1.00 before every value recorded, each claim taking the one in force on
 * its date ('0.00', no floor, until the settings are read).
 */
export function useFloor(sheetId: string): Dated {
  const settings = useSettings(sheetId).data;
  if (!settings) return { start: '0.00', values: [] };
  return { start: '1.00', values: settings.dated?.floor ?? [] };
}

/**
 * What the sheet's late charge and rounding need: its late percent ('0.00' until read),
 * today and policy date ('' until read).
 */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const pct: Dated = { start: '0.00', values: settings?.dated?.['late-pct'] ?? [] };
  return { pct, today: useSheetToday(sheetId), policyDate: settings?.policyDate ?? '' };
}

/** The sheet's cap on a person's due-total ('' for none, until the settings are read). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The roles assigned on the sheet, by user name. */
export function useRoles(sheetId: string) {
  return useQuery({
    queryKey: rolesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ roles: Role[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`)).roles,
  });
}

/** A clerk limit as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const LIMIT = /^\d+(\.\d{1,2})?$/;

/** A cap as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const CAP = /^\d+(\.\d{1,2})?$/;

/** A proof threshold as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const PROOF_THRESHOLD = /^\d+(\.\d{1,2})?$/;

/** A floor as the screen takes it: 0.00 or more with up to two decimals. */
export const FLOOR = /^\d+(\.\d{1,2})?$/;

/** A late percent as the screen takes it: 0.00 or more with up to two decimals. */
export const LATE_PCT = /^\d+(\.\d{1,2})?$/;

/** A policy date as the screen takes it: blank, or a date yyyy-MM-dd. */
export const POLICY_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Terms as the screen takes them: a whole number of days, 0 or more. */
export const TERMS = /^\d{1,5}$/;
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { CAP, DATED_KEYS, FLOOR, GRADES, LATE_PCT, LIMIT, POLICY_DATE, PROOF_THRESHOLD, TERMS, ROLES, rolesKey, settingsKey, useRoles, useSettings } from './access';
import type { Role, Settings, SettingsChange } from './access';

type Key = Exclude<keyof Settings, 'gradeTerms'>;

// The sheet's settings: its clerk limit, the highest due a clerk may settle (blank: no limit), and
// its floor, the least a claim's live due may be, and its terms, the days after a claim's date that
// it is due by, and its late percent, what an overdue claim's due gains per full 30 days overdue, and
// its policy date (blank: the sheet's today), before which a claim rounds half up, and its period
// numbering from (blank: off), from which a claim opened is numbered within its period, and each
// grade's own terms (blank: the sheet's terms), fixing the due-by of a claim made for it, and its cap
// (blank: none), the most a person's due-total may be, and its proof threshold (blank: none), above
// which a claim's due, on its date, needs a proof to be settled or approved. Only the settings typed in (or stepped into)
// since the last save are sent, so saving one leaves the other as it is.
function SettingsForm({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const settings = useSettings(sheetId);
  const [fields, setFields] = useState<Omit<Settings, 'gradeTerms'>>({
    cap: '',
    proofThreshold: '',
    clerkLimit: '',
    floor: '',
    terms: '',
    latePct: '',
    policyDate: '',
    periodNumberingFrom: '',
  });
  const [touched, setTouched] = useState<Set<Key>>(new Set());
  const [gradeFields, setGradeFields] = useState<Record<string, string>>({});
  const [gradesTouched, setGradesTouched] = useState<Set<string>>(new Set());
  // The from-date typed for each figure setting, by its store key (blank: the sheet's today).
  const [fromFields, setFromFields] = useState<Record<string, string>>({});
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const save = useMutation({
    mutationFn: (body: SettingsChange) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, body, user),
    onSuccess: (saved) => {
      setTouched(new Set());
      setGradesTouched(new Set());
      queryClient.setQueryData(settingsKey(sheetId), saved);
    },
    onError: () => setError('Those settings could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const body: SettingsChange = {};
    if (touched.has('clerkLimit')) {
      const clerkLimit = fields.clerkLimit.trim();
      if (clerkLimit !== '' && !LIMIT.test(clerkLimit)) {
        setError('A clerk limit is 0.00 or more, with up to two decimals.');
        return;
      }
      body.clerkLimit = clerkLimit;
    }
    if (touched.has('floor')) {
      const floor = fields.floor.trim();
      if (!FLOOR.test(floor)) {
        setError('A floor is 0.00 or more, with up to two decimals.');
        return;
      }
      body.floor = floor;
    }
    if (touched.has('terms')) {
      const terms = fields.terms.trim();
      if (!TERMS.test(terms)) {
        setError('Terms are a whole number of days, 0 or more.');
        return;
      }
      body.terms = terms;
    }
    if (touched.has('latePct')) {
      const latePct = fields.latePct.trim();
      if (!LATE_PCT.test(latePct)) {
        setError('A late percent is 0.00 or more, with up to two decimals.');
        return;
      }
      body.latePct = latePct;
    }
    if (touched.has('policyDate')) {
      const policyDate = fields.policyDate.trim();
      if (policyDate !== '' && (!POLICY_DATE.test(policyDate) || Number.isNaN(Date.parse(policyDate)))) {
        setError('A policy date is a date, yyyy-MM-dd, or blank.');
        return;
      }
      body.policyDate = policyDate;
    }
    if (touched.has('periodNumberingFrom')) {
      const from = fields.periodNumberingFrom.trim();
      if (from !== '' && (!POLICY_DATE.test(from) || Number.isNaN(Date.parse(from)))) {
        setError('A period numbering from is a date, yyyy-MM-dd, or blank.');
        return;
      }
      body.periodNumberingFrom = from;
    }
    if (touched.has('cap')) {
      const cap = fields.cap.trim();
      if (cap !== '' && !CAP.test(cap)) {
        setError('A cap is 0.00 or more, with up to two decimals, or blank.');
        return;
      }
      body.cap = cap;
    }
    if (touched.has('proofThreshold')) {
      const threshold = fields.proofThreshold.trim();
      if (threshold !== '' && !PROOF_THRESHOLD.test(threshold)) {
        setError('A proof threshold is 0.00 or more, with up to two decimals, or blank.');
        return;
      }
      body.proofThreshold = threshold;
    }
    if (gradesTouched.size > 0) {
      const gradeTerms: Record<string, string> = {};
      for (const grade of GRADES) {
        if (!gradesTouched.has(grade)) continue;
        const terms = (gradeFields[grade] ?? '').trim();
        if (terms !== '' && !TERMS.test(terms)) {
          setError(`Terms for grade ${grade} are a whole number of days, 0 or more, or blank.`);
          return;
        }
        gradeTerms[grade] = terms;
      }
      body.gradeTerms = gradeTerms;
    }
    const from: Record<string, string> = {};
    const datedKeys: string[] = [
      ...Object.entries(DATED_KEYS).filter(([key]) => touched.has(key as Key)).map(([, store]) => store),
      ...GRADES.filter((grade) => gradesTouched.has(grade)).map((grade) => `terms-${grade}`),
    ];
    for (const key of datedKeys) {
      const date = (fromFields[key] ?? '').trim();
      if (date === '') continue;
      if (!POLICY_DATE.test(date) || Number.isNaN(Date.parse(date))) {
        setError('A from-date is a date, yyyy-MM-dd, or blank.');
        return;
      }
      from[key] = date;
    }
    if (Object.keys(from).length > 0) body.from = from;
    if (Object.keys(body).length === 0) {
      setError('Type a setting to save.');
      return;
    }
    once((done) => save.mutate(body, { onSettled: done }));
  };

  const touch = (key: Key) => setTouched((t) => (t.has(key) ? t : new Set(t).add(key)));
  const change = (key: Key, value: string) => {
    setFields((f) => ({ ...f, [key]: value }));
    touch(key);
    setError('');
  };
  const changeFrom = (key: string, value: string) => {
    setFromFields((f) => ({ ...f, [key]: value }));
    setError('');
  };
  // The from-date input of a figure setting: blank saves it from the sheet's today.
  const fromInput = (key: string) => (
    <label>
      from{' '}
      <input
        data-testid={`setting-${key}-from`}
